// ProductServiceServer is the server API for ProductService service.
// All implementations must embed UnimplementedProductServiceServer
// for forward compatibility.
type ProductServiceServer interface {
	// 分类
	ListCategories(context.Context, *ListCategoriesReq) (*ListCategoriesResp, error)
	GetCategory(context.Context, *GetCategoryReq) (*CategoryInfo, error)
	CreateCategory(context.Context, *CreateCategoryReq) (*CategoryInfo, error)
	UpdateCategory(context.Context, *UpdateCategoryReq) (*CategoryInfo, error)
	DeleteCategory(context.Context, *DeleteCategoryReq) (*common.CommonResponse, error)
	// 商品
	ListProducts(context.Context, *ListProductsReq) (*ListProductsResp, error)
	GetProduct(context.Context, *GetProductReq) (*ProductDetail, error)
	SearchProducts(context.Context, *SearchProductsReq) (*ListProductsResp, error)
	CreateProduct(context.Context, *CreateProductReq) (*ProductDetail, error)
	UpdateProduct(context.Context, *UpdateProductReq) (*ProductDetail, error)
	DeleteProduct(context.Context, *DeleteProductReq) (*common.CommonResponse, error)
	UpdateProductStatus(context.Context, *UpdateProductStatusReq) (*common.CommonResponse, error)
	// SKU
	ListSkus(context.Context, *ListSkusReq) (*ListSkusResp, error)
	CreateSku(context.Context, *CreateSkuReq) (*SkuInfo, error)
	UpdateSku(context.Context, *UpdateSkuReq) (*SkuInfo, error)
	GetSkuById(context.Context, *GetSkuByIdReq) (*SkuInfo, error)
	// 库存
	DeductStock(context.Context, *DeductStockReq) (*DeductStockResp, error)
	ReleaseStock(context.Context, *ReleaseStockReq) (*common.CommonResponse, error)
	StockEntry(context.Context, *StockEntryReq) (*common.CommonResponse, error)
	StockOut(context.Context, *StockOutReq) (*common.CommonResponse, error)
	ListStockRecords(context.Context, *ListStockRecordsReq) (*ListStockRecordsResp, error)
	GetStockWarnings(context.Context, *GetStockWarningsReq) (*ListStockWarningsResp, error)
	GeneratePurchaseOrder(context.Context, *GeneratePurchaseOrderReq) (*GeneratePurchaseOrderResp, error)
	// 盘点
	CreateStockCheck(context.Context, *CreateStockCheckReq) (*StockCheckInfo, error)
	SubmitStockCheck(context.Context, *SubmitStockCheckReq) (*common.CommonResponse, error)
	ListStockChecks(context.Context, *ListStockChecksReq) (*ListStockChecksResp, error)
	GetStockCheck(context.Context, *GetStockCheckReq) (*StockCheckDetail, error)
	// 定价
	SetCommunityPricing(context.Context, *SetPricingReq) (*common.CommonResponse, error)
	ListCommunityPricing(context.Context, *ListPricingReq) (*ListPricingResp, error)
	GetReferencePricing(context.Context, *GetReferencePricingReq) (*ListPricingResp, error)
	// 营销
	ListCoupons(context.Context, *ListCouponsReq) (*ListCouponsResp, error)
	GetCoupon(context.Context, *GetCouponReq) (*CouponInfo, error)
	CreateCoupon(context.Context, *CreateCouponReq) (*CouponInfo, error)
	UpdateCoupon(context.Context, *UpdateCouponReq) (*CouponInfo, error)
	DeleteCoupon(context.Context, *DeleteCouponReq) (*common.CommonResponse, error)
	ReceiveCoupon(context.Context, *ReceiveCouponReq) (*common.CommonResponse, error)
	ListUserCoupons(context.Context, *ListUserCouponsReq) (*ListUserCouponsResp, error)
	UseCoupon(context.Context, *UseCouponReq) (*common.CommonResponse, error)
	ListFlashSales(context.Context, *ListFlashSalesReq) (*ListFlashSalesResp, error)
	GetFlashSale(context.Context, *GetFlashSaleReq) (*FlashSaleDetail, error)
	CreateFlashSale(context.Context, *CreateFlashSaleReq) (*FlashSaleInfo, error)
	UpdateFlashSale(context.Context, *UpdateFlashSaleReq) (*FlashSaleInfo, error)
	ListFullReductions(context.Context, *ListFullReductionsReq) (*ListFullReductionsResp, error)
	CreateFullReduction(context.Context, *CreateFullReductionReq) (*FullReductionInfo, error)
	UpdateFullReduction(context.Context, *UpdateFullReductionReq) (*FullReductionInfo, error)
	// 满额免配送费活动
	ListFreeShippings(context.Context, *ListFreeShippingsReq) (*ListFreeShippingsResp, error)
	CreateFreeShipping(context.Context, *CreateFreeShippingReq) (*FreeShippingInfo, error)
	UpdateFreeShipping(context.Context, *UpdateFreeShippingReq) (*FreeShippingInfo, error)
	GetActiveFreeShipping(context.Context, *GetActiveFreeShippingReq) (*GetActiveFreeShippingResp, error)
	// Banner
	ListBanners(context.Context, *ListBannersReq) (*ListBannersResp, error)
	CreateBanner(context.Context, *CreateBannerReq) (*BannerInfo, error)
	UpdateBanner(context.Context, *UpdateBannerReq) (*BannerInfo, error)
	DeleteBanner(context.Context, *DeleteBannerReq) (*common.CommonResponse, error)
	// 附件
	GetAttachmentConfig(context.Context, *common.Empty) (*AttachmentConfig, error)
	SaveAttachmentConfig(context.Context, *AttachmentConfig) (*common.CommonResponse, error)
	UploadImageLocal(context.Context, *UploadImageLocalReq) (*AttachmentInfo, error)
	AttachmentPresign(context.Context, *AttachmentPresignReq) (*AttachmentPresignResp, error)
	AttachmentConfirm(context.Context, *AttachmentConfirmReq) (*AttachmentInfo, error)
	ListAttachments(context.Context, *ListAttachmentsReq) (*ListAttachmentsResp, error)
	// 附件迁移（本地 → OSS）
	ScanAttachmentMigrate(context.Context, *common.Empty) (*AttachmentMigrateOverview, error)
	ListAttachmentMigrate(context.Context, *AttachmentMigrateListReq) (*AttachmentMigrateListResp, error)
	MigrateAttachmentItem(context.Context, *AttachmentMigrateItemReq) (*AttachmentMigrateItemInfo, error)
	VerifyAttachmentItem(context.Context, *AttachmentMigrateItemReq) (*AttachmentMigrateItemInfo, error)
	DeleteAttachmentLocal(context.Context, *AttachmentMigrateItemReq) (*AttachmentMigrateItemInfo, error)
	DeleteAttachmentLocalVerified(context.Context, *common.Empty) (*AttachmentMigrateDeleteBatchResp, error)
	mustEmbedUnimplementedProductServiceServer()
}

